// BRAND DEAL OUTREACH ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows and is generated from one file, so the
// sender and the reply handler can never disagree about which inbox belongs to which
// student, or about what counts as a booked deal.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what lets
// this be demonstrated on a screen-share before a single credential exists.

// ---------------------------------------------------------------- Airtable: the database
// The student dashboard the brief describes. Blank = the run uses the built-in demo roster
// and writes nothing.
//   API key:  airtable.com/create/tokens (a PAT with data.records:read and :write)
//   Base id:  the "app..." segment of the base's URL
const AIRTABLE_API_KEY = '';
const AIRTABLE_BASE_ID = '';
const AIRTABLE_URL     = 'https://api.airtable.com/v0';

const STUDENTS_TABLE = 'Students';   // one row per creator we send for
const BRANDS_TABLE   = 'Brands';     // the target list, per niche
const PITCHES_TABLE  = 'Pitches';    // one row per pitch. Written same day, always.
const INBOXES_TABLE  = 'Inboxes';    // sending accounts and their health

// Field names, exactly as they appear in Airtable.
const STUDENT_FIELDS = {
  student_id:   'Student id',
  name:         'Name',
  handle:       'Handle',
  niche:        'Niche',
  platform:     'Platform',
  followers:    'Followers',
  avg_views:    'Average views',
  rate_card:    'Rate card',
  min_rate:     'Minimum rate',
  deliverables: 'Deliverables',
  proof:        'Proof points',
  status:       'Status',
  started_on:   'Engagement start',
  monthly_target: 'Monthly pitch target'
};

const BRAND_FIELDS = {
  brand_id:     'Brand id',
  brand:        'Brand',
  niche:        'Niche',
  contact_name: 'Contact name',
  contact_email: 'Contact email',
  role:         'Role',
  budget_band:  'Budget band',
  recent_signal: 'Recent signal',
  product:      'Product',
  region:       'Region',
  status:       'Status'
};

const PITCH_FIELDS = {
  pitch_id:    'Pitch id',
  student_id:  'Student id',
  student:     'Student',
  brand_id:    'Brand id',
  brand:       'Brand',
  contact:     'Contact',
  email:       'Email',
  inbox:       'Sent from',
  subject:     'Subject',
  body:        'Body',
  facts_used:  'Facts used',
  sent_at:     'Sent at',
  state:       'State',
  hold_reason: 'Hold reason',
  reply_at:    'Replied at',
  reply_class: 'Reply',
  booked_at:   'Booked at',
  deal_value:  'Deal value'
};

const INBOX_FIELDS = {
  inbox_id:     'Inbox id',
  email:        'Email',
  domain:       'Domain',
  student_id:   'Student id',
  warmed_days:  'Days warming',
  daily_cap:    'Daily cap',
  sent_today:   'Sent today',
  bounce_rate:  'Bounce rate',
  spam_rate:    'Spam complaint rate',
  health_score: 'Health score',
  state:        'State'
};

// Only students in these states are pitched for.
const ACTIVE_STUDENT_STATES = ['Active', 'Onboarding complete', ''];
// Only brands in these states are pitched. Anything else has been contacted or ruled out.
const OPEN_BRAND_STATES = ['New', 'Researched', ''];

// ---------------------------------------------------------------- Volume
// The brief's number is 10,000+ pitches a month across all students. That is a per-student
// daily figure once you divide it by working days, and it is the figure that has to be
// enforced — a month's target is not a thing you can rate-limit against.
const PITCHES_PER_STUDENT_PER_DAY = 25;
const DAILY_CAP                   = 400;  // hard ceiling across all students, per run
const MAX_PER_BRAND_PER_STUDENT   = 1;    // never pitch the same brand twice for one creator
const REPITCH_AFTER_DAYS          = 90;   // a brand that said no is left alone this long

// ---------------------------------------------------------------- Deliverability
// The second of their three hard gates. This is the part that fails CLOSED: an inbox that
// cannot be proved healthy does not send. Every other mistake in cold outreach is
// recoverable; a burnt sending domain is not, and it takes the student's name with it.
const MIN_WARMUP_DAYS   = 14;    // an inbox younger than this sends nothing
const MAX_BOUNCE_RATE   = 0.03;  // 3% — above this the inbox is pulled from rotation
const MAX_SPAM_RATE     = 0.001; // 0.1%
const MIN_HEALTH_SCORE  = 70;    // whatever your sending platform reports, 0-100
const MAX_PER_INBOX_DAY = 40;    // per mailbox, not per domain
const MAX_PER_DOMAIN_DAY = 120;  // across every mailbox on one domain

// An inbox whose health the platform will not tell us about. true = do not send from it.
// Leave it true: an unknown inbox is not a healthy one.
const HOLD_UNKNOWN_INBOX = true;

// ---------------------------------------------------------------- Personalisation
// Their third hard gate: "pitches read human and personal from line one. Never templated."
//
// A pitch must carry at least MIN_FACTS specific, verifiable details drawn from the BRAND
// and STUDENT records — not from the model. If the record does not contain enough to say
// something true and specific, the pitch is HELD, not sent with a generic line in its place.
// That is the difference between personalisation and mail-merge, and it is checkable.
const MIN_FACTS = 3;

// And at least this many of them about the BRAND. Creator numbers are facts too, but a
// pitch made only of them is a CV — MIN_FACTS alone would let one through on the strength
// of the follower count.
const MIN_BRAND_FACTS = 2;

// Which brand record fields count as a usable fact. A blank field is not a fact.
//
// `budget_band` is deliberately NOT here. It is real, and it gates the match upstream, and
// it must never appear in an email — telling a company what you think their budget is, is
// the single fastest way to lose the deal you were quoting into.
const FACT_FIELDS = ['recent_signal', 'product', 'role'];

// Phrases that give a template away. A pitch containing any of these is held and rewritten.
// This list is the single most useful thing in this config — add to it every time you read
// a sent pitch and wince.
const BANNED_PHRASES = [
  'i hope this email finds you well', 'i hope this finds you well', 'quick question',
  'just following up', 'circling back', 'touching base', 'i wanted to reach out',
  'i came across your', 'i stumbled upon', 'love what you are doing',
  'love what you’re doing', 'we are a leading', 'synergy', 'game-changing',
  'revolutionary', 'to whom it may concern', 'dear sir or madam', 'per my last email',
  'as per', 'kindly revert', 'i am reaching out to you today'
];

// A pitch outside this range is held. Short enough to read on a phone, long enough to say
// something.
const MIN_WORDS = 60;
const MAX_WORDS = 160;

// Never send to these. Domains or full addresses. Anything that replies "remove me" is
// added here by workflow 02.
const SUPPRESSION = [];

// Role mailboxes nobody owns. Held — these are where bounce rates come from.
const ROLE_PREFIXES = ['info', 'hello', 'contact', 'support', 'admin', 'sales', 'help',
  'noreply', 'no-reply', 'press', 'careers', 'jobs', 'legal', 'billing', 'webmaster'];

// ---------------------------------------------------------------- The writer
// The model rewrites the SUBJECT and the OPENING LINE around facts that were assembled in
// code. It is never handed the rate card and asked to improvise a number.
// Blank = the skeleton pitch is produced and held for a human to finish. Nothing is sent
// unwritten.
const AI_API_KEY = '';
const AI_URL     = 'https://api.anthropic.com/v1/messages';
const AI_MODEL   = 'claude-opus-5';

// ---------------------------------------------------------------- The sending engine
// Instantly by default. Smartlead works the same way: change SEND_URL and the body built in
// "payload for the campaign".
const SEND_API_KEY  = '';
const SEND_URL      = 'https://api.instantly.ai/api/v2/leads';
const REPLIES_URL   = 'https://api.instantly.ai/api/v2/emails';
const CAMPAIGN_ID   = '';

// Optional: a different campaign per niche, so a skincare brand and a gaming brand are not
// sent the same sequence. Anything not listed here goes to CAMPAIGN_ID.
const CAMPAIGN_BY_NICHE = {
  // 'Beauty': 'campaign-uuid-here',
  // 'Gaming': 'campaign-uuid-here'
};

// ---------------------------------------------------------------- Replies (workflow 02)
// How a reply is classified. First rule whose words appear wins, so put the specific ones
// first. Anything that matches nothing is 'unclear' and goes to a human — never guessed.
const REPLY_RULES = [
  { klass: 'unsubscribe', route: 'suppress',
    words: ['unsubscribe', 'remove me', 'take me off', 'do not contact', 'opt out',
            'stop emailing'] },
  { klass: 'auto-reply', route: 'ignore',
    words: ['out of office', 'automatic reply', 'auto-reply', 'annual leave',
            'on holiday', 'currently away', 'parental leave'] },
  { klass: 'bounce', route: 'suppress',
    words: ['undeliverable', 'delivery failed', 'address not found', 'mailbox full',
            'recipient rejected', 'does not exist'] },
  { klass: 'wrong-person', route: 'reroute',
    words: ['no longer with', 'has left', 'not the right person', 'forward this to',
            'my colleague handles', 'wrong department'] },
  { klass: 'not-now', route: 'nurture',
    words: ['next quarter', 'next year', 'budget is set', 'revisit', 'not right now',
            'circle back in', 'check back'] },
  { klass: 'not-interested', route: 'close',
    words: ['not interested', 'no thanks', 'we will pass', 'we’ll pass', 'not a fit',
            'not for us', 'declining'] },
  { klass: 'interested', route: 'handover',
    words: ['interested', 'tell me more', 'send over', 'rates', 'media kit', 'happy to chat',
            'set up a call', 'what would', 'pricing', 'sounds good', 'let’s talk'] }
];

// A reply routed 'handover' is a human's job — the brief pays a person to work the replies,
// and this workflow's job is to put the right ones in front of them fast, not to negotiate.
const HANDOVER_WEBHOOK_URL = '';   // Slack channel for interested replies. Blank = summary only.

// ---------------------------------------------------------------- Weekly report
// "Report weekly — clean numbers so students and the team can see progress."
// Runs on the hourly trigger, on this day and hour only.
const REPORT_DAY  = 1;   // 0 Sunday … 6 Saturday
const REPORT_HOUR = 9;   // 24h, in the n8n instance's timezone
const REPORT_WINDOW_DAYS = 7;

const ALERT_WEBHOOK_URL = '';   // Slack incoming webhook for the run summaries.

// ---------------------------------------------------------------- Demo mode
// With no Airtable key set, builds a deterministic roster — six students, sixty brands,
// four inboxes with a realistic spread of health — so the whole engine can be watched end
// to end before an account exists. While this is on the run is FORCED into preview: a
// fabricated brand contact can never be emailed.
const DEMO_ROSTER = true;

// ---------------------------------------------------------------- Safety switch
//   TEST_RUN true,  TEST_EMAIL blank -> PREVIEW. Every pitch is written, audited and
//                                       assigned an inbox, and NOTHING is sent or logged.
//                                       Ships this way.
//   TEST_RUN true,  TEST_EMAIL set   -> TEST. Pitches really are sent, all redirected to
//                                       that address, so you can read what a brand would get.
//   TEST_RUN false                   -> LIVE.
const TEST_RUN   = true;
const TEST_EMAIL = '';

const DEMO_DATA = DEMO_ROSTER === true && AIRTABLE_API_KEY.trim() === '';

let MODE = TEST_RUN !== true ? 'live'
  : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');

// A fabricated brand contact is not a lead. It cannot open the send gate, whatever
// TEST_RUN says.
const FORCED_PREVIEW = DEMO_DATA && MODE !== 'preview';
if (FORCED_PREVIEW) MODE = 'preview';

const now = new Date();
const REPORT_DUE = now.getDay() === Number(REPORT_DAY) &&
                   now.getHours() === Number(REPORT_HOUR);

return [{
  json: {
    airtable_url:  AIRTABLE_URL,
    airtable_key:  AIRTABLE_API_KEY.trim(),
    airtable_base: AIRTABLE_BASE_ID.trim(),
    students_table: STUDENTS_TABLE,
    brands_table:   BRANDS_TABLE,
    pitches_table:  PITCHES_TABLE,
    inboxes_table:  INBOXES_TABLE,
    student_fields: STUDENT_FIELDS,
    brand_fields:   BRAND_FIELDS,
    pitch_fields:   PITCH_FIELDS,
    inbox_fields:   INBOX_FIELDS,
    active_student_states: ACTIVE_STUDENT_STATES,
    open_brand_states:     OPEN_BRAND_STATES,

    pitches_per_student_per_day: Number(PITCHES_PER_STUDENT_PER_DAY) || 25,
    daily_cap:                   Number(DAILY_CAP) || 0,
    max_per_brand_per_student:   Number(MAX_PER_BRAND_PER_STUDENT) || 1,
    repitch_after_days:          Number(REPITCH_AFTER_DAYS) || 90,

    min_warmup_days:    Number(MIN_WARMUP_DAYS) || 0,
    max_bounce_rate:    Number(MAX_BOUNCE_RATE) || 0,
    max_spam_rate:      Number(MAX_SPAM_RATE) || 0,
    min_health_score:   Number(MIN_HEALTH_SCORE) || 0,
    max_per_inbox_day:  Number(MAX_PER_INBOX_DAY) || 0,
    max_per_domain_day: Number(MAX_PER_DOMAIN_DAY) || 0,
    hold_unknown_inbox: HOLD_UNKNOWN_INBOX !== false,

    min_facts:       Number(MIN_FACTS) || 0,
    min_brand_facts: Number(MIN_BRAND_FACTS) || 0,
    fact_fields: FACT_FIELDS,
    banned_phrases: BANNED_PHRASES.map(function (p) { return String(p).toLowerCase(); }),
    min_words:   Number(MIN_WORDS) || 0,
    max_words:   Number(MAX_WORDS) || 9999,
    suppression: SUPPRESSION.map(function (s) { return String(s).trim().toLowerCase(); })
      .filter(Boolean),
    role_prefixes: ROLE_PREFIXES,

    ai_api_key: AI_API_KEY.trim(),
    ai_url:     AI_URL,
    ai_model:   AI_MODEL,

    send_api_key: SEND_API_KEY.trim(),
    send_url:     SEND_URL,
    replies_url:  REPLIES_URL,
    campaign_id:  CAMPAIGN_ID.trim(),
    campaign_by_niche: CAMPAIGN_BY_NICHE,

    reply_rules: REPLY_RULES,
    handover_webhook_url: HANDOVER_WEBHOOK_URL.trim(),

    report_day:  Number(REPORT_DAY),
    report_hour: Number(REPORT_HOUR),
    report_window_days: Number(REPORT_WINDOW_DAYS) || 7,
    alert_webhook_url:  ALERT_WEBHOOK_URL.trim(),
    test_email: TEST_EMAIL.trim(),

    // derived flags — the gates read these, never the raw constants
    mode:         MODE,
    preview_only: MODE === 'preview',
    test_send:    MODE === 'test',
    live_send:    MODE === 'live',

    airtable_enabled: AIRTABLE_API_KEY.trim() !== '' && AIRTABLE_BASE_ID.trim() !== '',
    log_enabled:      MODE !== 'preview' && AIRTABLE_API_KEY.trim() !== ''
                      && AIRTABLE_BASE_ID.trim() !== '',
    ai_enabled:       AI_API_KEY.trim() !== '',
    send_enabled:     MODE !== 'preview' && SEND_API_KEY.trim() !== '' &&
                      CAMPAIGN_ID.trim() !== '',
    replies_enabled:  SEND_API_KEY.trim() !== '',
    alert_enabled:    ALERT_WEBHOOK_URL.trim() !== '',
    handover_enabled: (HANDOVER_WEBHOOK_URL.trim() || ALERT_WEBHOOK_URL.trim()) !== '',
    handover_url:     HANDOVER_WEBHOOK_URL.trim() || ALERT_WEBHOOK_URL.trim(),
    report_due:       REPORT_DUE,
    demo_data:        DEMO_DATA,
    forced_preview:   FORCED_PREVIEW
  }
}];

// Folds the four Airtable reads into ONE item shaped {students, brands, inboxes, pitches}.
//
// Everything downstream reads this shape and never touches an Airtable response directly,
// so the demo roster and the real base are interchangeable from here on.
const cfg = $('config').first().json;

const S = cfg.student_fields;
const B = cfg.brand_fields;
const P = cfg.pitch_fields;
const I = cfg.inbox_fields;

const failures = [];
function records(payload, what) {
  if (!payload || payload.error || !Array.isArray(payload.records)) {
    failures.push(what + ': ' + ((payload && payload.error &&
      (payload.error.message || payload.error)) || 'no response'));
    return [];
  }
  return payload.records;
}

function map(rows, fields) {
  return rows.map(function (r) {
    const f = r.fields || {};
    const out = { _record_id: r.id };
    Object.keys(fields).forEach(function (key) { out[key] = f[fields[key]]; });
    return out;
  });
}

const students = map(records($('[cred] Airtable - students').first().json, 'students'), S);
const brands = map(records($('[cred] Airtable - brand targets').first().json, 'brands'), B);
const inboxes = map(records($('[cred] Airtable - inboxes').first().json, 'inboxes'), I);
const pitches = map(records($('[cred] Airtable - the pitch log').first().json, 'pitches'), P);

// An empty read that did not error is a real state — a roster with nobody active. An empty
// read that DID error must never look like one, because the difference is between "nothing
// to send today" and "we stopped sending and nobody noticed".
if (failures.length && students.length === 0) {
  throw new Error('Airtable returned nothing usable (' + failures.join('; ') +
    '). Refusing to report an empty roster as a quiet day.');
}

return [{
  json: {
    source: 'airtable',
    read_at: new Date().toISOString(),
    failures: failures,
    students: students.filter(function (s) {
      return cfg.active_student_states.indexOf(String(s.status || '')) !== -1;
    }),
    brands: brands.filter(function (b) {
      return cfg.open_brand_states.indexOf(String(b.status || '')) !== -1;
    }),
    inboxes: inboxes,
    pitches: pitches
  }
}];

// STOP: Airtable is not configured — build the demo roster instead.
//
// Deterministic. Six students across six niches, sixty brand contacts, four sending inboxes
// with a deliberately mixed health picture — one still warming, one over its bounce
// threshold, one whose health the platform will not report, one clean — and a pitch history
// so the dedupe has something to catch.
//
// Nothing here can be emailed: `demo_data` forces the run into preview in config.
const cfg = $('config').first().json;

if (cfg.airtable_enabled) {
  throw new Error('demo roster reached with Airtable configured — check the IF gate');
}
if (!cfg.demo_data) {
  return [{ json: { source: 'none', read_at: new Date().toISOString(),
    students: [], brands: [], inboxes: [], pitches: [],
    _note: 'No Airtable key and DEMO_ROSTER is off. Nothing to work on.' } }];
}

const DAY = 86400000;
const now = Date.now();
function iso(ms) { return new Date(ms).toISOString(); }

let seed = 20260904;
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }

const STUDENTS = [
  ['ST-01', 'Nadia Osei', '@nadiabuilds', 'Home & interiors', 'Instagram', 84000, 21000,
   1400, 900, 'One in-feed reel + two stories',
   'Grew from 12k to 84k in fourteen months; 6.1% average engagement'],
  ['ST-02', 'Tomas Ferreira', '@tomcooks', 'Food', 'TikTok', 210000, 65000,
   2200, 1500, 'One 45-second TikTok + usage rights',
   'Three videos past 1M views this year; audience 71% UK'],
  ['ST-03', 'Priya Raman', '@priyalifts', 'Fitness', 'Instagram', 46000, 12000,
   900, 600, 'Two in-feed posts',
   '4.8% engagement; 63% of audience aged 25-34'],
  ['ST-04', 'Leo Hartmann', '@leoplays', 'Gaming', 'YouTube', 320000, 48000,
   3500, 2400, 'One 60-second integration',
   'Averages 48k views per upload across the last twenty videos'],
  ['ST-05', 'Amara Chike', '@amaraskin', 'Beauty', 'TikTok', 128000, 39000,
   1800, 1200, 'One TikTok + one story set',
   'Two brand videos past 500k views; 82% female audience'],
  ['ST-06', 'Iris Vandermeer', '@irisdraws', 'Art & craft', 'Instagram', 61000, 15000,
   1100, 700, 'One carousel + two stories',
   'Featured twice by the platform editorial team']
];

const BRANDS = [
  ['Home & interiors', 'Kestrel Living', 'Sofie Brandt', 'Head of Brand',
   'launched a spring modular sofa line last month', 'Modular sofas', 'UK', '1-3k'],
  ['Home & interiors', 'Northwood Ceramics', 'Ravi Menon', 'Marketing Manager',
   'opened a second showroom in Leeds', 'Handmade tableware', 'UK', 'under 1k'],
  ['Food', 'Copper Pot Sauces', 'Elena Ruiz', 'Growth Lead',
   'moved into 400 Tesco stores in March', 'Cooking sauces', 'UK', '1-3k'],
  ['Food', 'Grainhouse Bakery', 'Tom Aldridge', 'Founder',
   'started shipping nationwide in February', 'Sourdough kits', 'UK', 'under 1k'],
  ['Fitness', 'Vantage Athletic', 'Kim Dae-jung', 'Partnerships',
   'released a womens training range in April', 'Training apparel', 'EU', '3-5k'],
  ['Fitness', 'Rowan Supplements', 'Beth Okoye', 'Brand Manager',
   'reformulated their protein line without sweeteners', 'Protein powder', 'UK', '1-3k'],
  ['Gaming', 'Hexline Peripherals', 'Marc Dubois', 'Influencer Lead',
   'shipped a low-latency wireless mouse in May', 'Gaming mice', 'EU', '3-5k'],
  ['Gaming', 'Nightfall Studios', 'Sara Lindholm', 'Community Manager',
   'announced an early-access date for their roguelike', 'Indie game', 'Global', '1-3k'],
  ['Beauty', 'Lumen Skin', 'Aisha Rahman', 'Head of Growth',
   'reformulated their serum to fragrance-free in March', 'Vitamin C serum', 'UK', '1-3k'],
  ['Beauty', 'Verdant Haircare', 'Jonas Weber', 'Marketing Director',
   'launched a refill programme across their range', 'Shampoo bars', 'EU', '3-5k'],
  ['Art & craft', 'Paperfold Studio', 'Mei Tanaka', 'Founder',
   'released a limited watercolour set with an illustrator', 'Watercolour sets', 'UK', 'under 1k'],
  ['Art & craft', 'Inkwell Supply', 'Owen Blake', 'Partnerships',
   'opened wholesale to independent shops this quarter', 'Fountain pens', 'UK', '1-3k']
];

const students = STUDENTS.map(function (s, i) {
  return { student_id: s[0], name: s[1], handle: s[2], niche: s[3], platform: s[4],
    followers: s[5], avg_views: s[6], rate_card: s[7], min_rate: s[8], deliverables: s[9],
    proof: s[10], status: 'Active',
    started_on: iso(now - (20 + i * 6) * DAY),
    monthly_target: 400 };
});

// Sixty contacts: each seed brand cloned across regions so the matcher has volume to work
// with, which is what a 10,000-a-month brief actually looks like.
const REGIONS = ['UK', 'EU', 'US', 'AU', 'CA'];
const brands = [];
BRANDS.forEach(function (b, bi) {
  REGIONS.forEach(function (region, ri) {
    const n = bi * REGIONS.length + ri;
    const local = ri === 0;
    brands.push({
      brand_id: 'BR-' + String(n + 1).padStart(3, '0'),
      brand: local ? b[1] : b[1] + ' ' + region,
      niche: b[0],
      contact_name: local ? b[2] : b[2].split(' ')[0] + ' ' + ['Novak', 'Silva', 'Hughes',
        'Bauer', 'Moreau'][ri],
      // One in ten is a role mailbox, which the audit holds. They are where bounce rates
      // come from and a demo that never shows one is not showing the gate working.
      contact_email: (n % 10 === 3 ? 'info' : b[2].toLowerCase().split(' ')[0] + '.' +
        b[2].toLowerCase().split(' ')[1]) + '@' +
        b[1].toLowerCase().replace(/[^a-z]/g, '') + (local ? '.com' : '.' +
        region.toLowerCase()),
      role: n % 7 === 5 ? '' : b[3],
      // One in seven is a thin scraped record — the company and the product, and nothing
      // else. The personalisation gate has to hold those: nothing true and specific to say
      // means no pitch, not a generic one.
      recent_signal: n % 7 === 5 ? '' : b[4],
      product: b[5],
      region: region,
      budget_band: b[7],
      status: 'New'
    });
  });
});

const inboxes = [
  { inbox_id: 'IN-1', email: 'nadia@northbeam-outreach.example', domain: 'northbeam-outreach.example',
    student_id: '', warmed_days: 62, daily_cap: 40, sent_today: 0, bounce_rate: 0.006,
    spam_rate: 0.0002, health_score: 94, state: 'Active' },
  { inbox_id: 'IN-2', email: 'tomas@northbeam-outreach.example', domain: 'northbeam-outreach.example',
    student_id: '', warmed_days: 58, daily_cap: 40, sent_today: 12, bounce_rate: 0.011,
    spam_rate: 0.0004, health_score: 88, state: 'Active' },
  // Still warming — sends nothing, whatever else is true of it.
  { inbox_id: 'IN-3', email: 'priya@northbeam-reach.example', domain: 'northbeam-reach.example',
    student_id: '', warmed_days: 6, daily_cap: 40, sent_today: 0, bounce_rate: 0.002,
    spam_rate: 0, health_score: 91, state: 'Warming' },
  // Over the bounce threshold — pulled from rotation until somebody cleans the list.
  { inbox_id: 'IN-4', email: 'leo@northbeam-reach.example', domain: 'northbeam-reach.example',
    student_id: '', warmed_days: 71, daily_cap: 40, sent_today: 4, bounce_rate: 0.052,
    spam_rate: 0.0009, health_score: 74, state: 'Active' },
  // The platform will not report health for this one. HOLD_UNKNOWN_INBOX decides.
  { inbox_id: 'IN-5', email: 'amara@northbeam-mail.example', domain: 'northbeam-mail.example',
    student_id: '', warmed_days: 40, daily_cap: 40, sent_today: 0, bounce_rate: null,
    spam_rate: null, health_score: null, state: 'Active' },
  { inbox_id: 'IN-6', email: 'iris@northbeam-mail.example', domain: 'northbeam-mail.example',
    student_id: '', warmed_days: 45, daily_cap: 40, sent_today: 3, bounce_rate: 0.008,
    spam_rate: 0.0001, health_score: 85, state: 'Active' }
];

// A pitch history, so the dedupe and the re-pitch window have something to catch.
const pitches = [];
students.forEach(function (s, si) {
  const pool = brands.filter(function (b) { return b.niche === s.niche; });
  pool.slice(0, 4).forEach(function (b, bi) {
    const age = bi === 0 ? 10 : (cfg.repitch_after_days + 30);
    pitches.push({
      pitch_id: 'P-' + s.student_id + '-' + b.brand_id,
      student_id: s.student_id, student: s.name,
      brand_id: b.brand_id, brand: b.brand,
      contact: b.contact_name, email: b.contact_email,
      inbox: inboxes[si % inboxes.length].email,
      subject: '', body: '', facts_used: '',
      sent_at: iso(now - age * DAY),
      state: bi % 2 === 0 ? 'Sent' : 'Closed',
      hold_reason: '', reply_at: '', reply_class: '', booked_at: '', deal_value: ''
    });
  });
});

return [{
  json: {
    source: 'demo',
    read_at: new Date().toISOString(),
    failures: [],
    students: students,
    brands: brands,
    inboxes: inboxes,
    pitches: pitches,
    _note: 'DEMO ROSTER — ' + students.length + ' students, ' + brands.length +
           ' brand contacts, ' + inboxes.length + ' inboxes, ' + pitches.length +
           ' pitches already sent. The run is forced into preview; nothing here can be ' +
           'emailed.'
  }
}];

// One candidate pitch per item: this creator, this brand contact, today.
//
// "Each matched to their niche and rates" is the brief's own phrasing, and both halves are
// enforced here rather than left to the writer:
//
//   niche  a brand is only ever offered to a creator in the same niche. A gaming creator
//          does not get a skincare brand because the volume target was short today.
//   rates  a brand whose budget band tops out below the creator's minimum is not pitched
//          at all. Sending it wastes the send, and it wastes the reply the person working
//          the inbox has to read.
//
// Everything the dedupe needs comes from the pitch log, which is why that log has to be
// written same-day. A log written tomorrow is a duplicate sent today.
const cfg = $('config').first().json;
const roster = $json;

const DAY = 86400000;
const now = Date.now();

// Budget bands, lowest ceiling first. A band the config does not know is treated as
// unknown, and unknown never blocks a pitch — it is a soft signal, not a gate.
const BAND_CEILING = { 'under 1k': 1000, '1-3k': 3000, '3-5k': 5000, '5-10k': 10000,
  '10k+': 100000 };

function stamp(s) {
  if (!s) return null;
  const ms = Date.parse(String(s));
  return isNaN(ms) ? null : ms;
}

// What has already been sent, per student and per brand.
const sentByStudentBrand = {};
const sentByStudentToday = {};
const today = new Date().toISOString().slice(0, 10);
(roster.pitches || []).forEach(function (p) {
  const key = p.student_id + '|' + p.brand_id;
  const at = stamp(p.sent_at);
  if (!sentByStudentBrand[key] || at > sentByStudentBrand[key]) {
    sentByStudentBrand[key] = at;
  }
  if (String(p.sent_at || '').slice(0, 10) === today) {
    sentByStudentToday[p.student_id] = (sentByStudentToday[p.student_id] || 0) + 1;
  }
});

const suppressed = cfg.suppression || [];
function isSuppressed(email) {
  const e = String(email || '').toLowerCase();
  const domain = e.split('@')[1] || '';
  return suppressed.indexOf(e) !== -1 || suppressed.indexOf(domain) !== -1;
}

const byNiche = {};
(roster.brands || []).forEach(function (b) {
  const k = String(b.niche || '');
  if (!byNiche[k]) byNiche[k] = [];
  byNiche[k].push(b);
});

const perStudent = Number(cfg.pitches_per_student_per_day || 25);
const cap = Number(cfg.daily_cap || 0);

const out = [];
const skipped = { already_pitched: 0, too_recent: 0, budget: 0, suppressed: 0,
  no_brands: 0, student_cap: 0 };
let total = 0;

(roster.students || []).forEach(function (student) {
  const pool = byNiche[String(student.niche || '')] || [];
  if (!pool.length) { skipped.no_brands++; return; }

  const alreadyToday = sentByStudentToday[student.student_id] || 0;
  let budget = Math.max(0, perStudent - alreadyToday);
  if (budget === 0) { skipped.student_cap++; return; }

  const minRate = Number(student.min_rate || 0);

  for (let i = 0; i < pool.length && budget > 0; i++) {
    const brand = pool[i];
    if (cap > 0 && total >= cap) break;

    const key = student.student_id + '|' + brand.brand_id;
    const last = sentByStudentBrand[key];
    if (last !== undefined && last !== null) {
      const days = (now - last) / DAY;
      if (Number(cfg.max_per_brand_per_student || 1) <= 1 &&
          days < Number(cfg.repitch_after_days || 90)) {
        skipped.too_recent++;
        continue;
      }
      if (days >= Number(cfg.repitch_after_days || 90)) {
        // Fine to pitch again — a no from last quarter is not a no forever.
      } else {
        skipped.already_pitched++;
        continue;
      }
    }

    if (isSuppressed(brand.contact_email)) { skipped.suppressed++; continue; }

    const ceiling = BAND_CEILING[String(brand.budget_band || '').toLowerCase()];
    if (ceiling !== undefined && minRate > 0 && ceiling < minRate) {
      skipped.budget++;
      continue;
    }

    total++;
    budget--;
    out.push({
      json: {
        _has_work: true,
        pitch_id: 'P-' + student.student_id + '-' + brand.brand_id + '-' +
          today.replace(/-/g, ''),
        student_id: student.student_id,
        student: student.name,
        handle: student.handle,
        niche: student.niche,
        platform: student.platform,
        followers: student.followers,
        avg_views: student.avg_views,
        rate_card: student.rate_card,
        min_rate: minRate,
        deliverables: student.deliverables,
        proof: student.proof,
        brand_id: brand.brand_id,
        brand: brand.brand,
        contact: brand.contact_name,
        email: brand.contact_email,
        role: brand.role,
        recent_signal: brand.recent_signal,
        product: brand.product,
        region: brand.region,
        budget_band: brand.budget_band,
        _roster: { source: roster.source, read_at: roster.read_at,
                   inboxes: roster.inboxes || [], students: (roster.students || []).length }
      }
    });
  }
});

if (!out.length) {
  return [{
    json: {
      _has_work: false,
      skipped: skipped,
      source: roster.source,
      read_at: roster.read_at,
      _note: 'Nothing to pitch: ' + Object.keys(skipped).map(function (k) {
        return k + ' ' + skipped[k];
      }).join(', ')
    }
  }];
}

out.forEach(function (item) {
  item.json._skipped = skipped;
  item.json._candidates = out.length;
});
return out;

// STOP: the matcher produced no candidates.
//
// Almost always a real, reportable state rather than a fault: every brand in a creator's
// niche has already been pitched inside the re-pitch window, or the day's per-student
// budget is already spent. The summary says which, by count, so a quiet morning can be
// told apart from a broken one.
const j = $json;
const s = j.skipped || {};

const reasons = [];
if (s.already_pitched) reasons.push(s.already_pitched + ' already pitched');
if (s.too_recent) reasons.push(s.too_recent + ' inside the re-pitch window');
if (s.budget) reasons.push(s.budget + ' under the creator’s minimum rate');
if (s.suppressed) reasons.push(s.suppressed + ' suppressed');
if (s.no_brands) reasons.push(s.no_brands + ' creators with no brands in their niche');
if (s.student_cap) reasons.push(s.student_cap + ' creators already at today’s budget');

return [{
  json: {
    _has_work: false,
    source: j.source,
    read_at: j.read_at,
    skipped: s,
    headline: reasons.length
      ? 'Nothing to pitch today: ' + reasons.join(', ') + '.'
      : 'Nothing to pitch today, and nothing was filtered out — check the roster is loading.',
    // No brands left in a niche is the one that needs a person. The rest are the system
    // working.
    needs_attention: (s.no_brands || 0) > 0 || reasons.length === 0,
    recorded_at: new Date().toISOString()
  }
}];

// Assembles the FACTS in code, then asks the model to write around them.
//
// This is the whole personalisation argument. The facts — what the brand just did, what the
// creator's numbers actually are, what the deliverable is, what it costs — are read out of
// the two records and never invented. The model gets them as a list and is asked for a
// subject line and an opening line, in a named voice, with an explicit instruction not to
// add anything that is not in the list.
//
// A brand record with nothing specific in it produces FEWER facts, not a vaguer sentence.
// If it falls below MIN_FACTS the audit downstream holds the pitch. That is the difference
// between personalisation and mail-merge: mail-merge always has something to say.
const cfg = $('config').first().json;
const p = $json;

function fact(label, value) {
  const v = String(value === undefined || value === null ? '' : value).trim();
  return v ? { label: label, value: v } : null;
}

// Brand-side facts. These are the ones that prove the pitch was written for this company
// and not for a list.
const brandFacts = [
  fact('recent_signal', p.recent_signal),
  fact('product', p.product),
  fact('region', p.region),
  fact('role', p.role),
  fact('budget_band', p.budget_band)
].filter(Boolean).filter(function (f) {
  return cfg.fact_fields.indexOf(f.label) !== -1;
});

// Creator-side facts. Numbers, from the record, never rounded up by a model.
const creatorFacts = [
  fact('followers', p.followers ? Number(p.followers).toLocaleString('en-GB') + ' followers on ' +
    p.platform : ''),
  fact('avg_views', p.avg_views ? Number(p.avg_views).toLocaleString('en-GB') +
    ' average views' : ''),
  fact('proof', p.proof),
  fact('deliverables', p.deliverables)
].filter(Boolean);

const facts = brandFacts.concat(creatorFacts);

// The skeleton. This is what gets sent if there is no writer configured — it is stiff, and
// it is true, and it is held for a human rather than sent as-is.
const skeleton = [
  'Hi ' + String(p.contact || '').split(' ')[0] + ',',
  '',
  p.recent_signal
    ? 'Saw that ' + p.brand + ' ' + p.recent_signal + '.'
    : 'Writing about ' + p.brand + '.',
  '',
  'I look after partnerships for ' + p.student + ' (' + p.handle + ') — ' +
    creatorFacts.map(function (f) { return f.value; }).slice(0, 2).join(', ') + '.',
  '',
  p.deliverables + ' runs ' + (p.rate_card ? '£' + p.rate_card : 'at our standard rate') +
    '. Worth a conversation?',
  '',
  '— Northbeam, on behalf of ' + p.student
].join('\n');

const system = [
  'You write cold outreach for a creator partnerships agency.',
  '',
  'Rules, all of them hard:',
  '1. Use ONLY the facts in the list. Do not add a claim, a number, a compliment or a',
  '   detail that is not in it. If the list is thin, write a shorter email.',
  '2. First line must be about the BRAND, not about the creator and not about you.',
  '3. No greetings-filler. Never "I hope this email finds you well", "quick question",',
  '   "I came across your", "love what you are doing" or anything of that family.',
  '4. British English. Plain. No adjectives you would not say out loud.',
  '5. ' + cfg.min_words + '-' + cfg.max_words + ' words in the body.',
  '6. One ask at the end, and make it easy to answer with one word.',
  '',
  'Return JSON only: {"subject": "...", "body": "..."}'
].join('\n');

const user = [
  'Brand: ' + p.brand,
  'Contact: ' + p.contact + (p.role ? ' (' + p.role + ')' : ''),
  'Creator: ' + p.student + ' ' + p.handle + ', ' + p.niche + ' on ' + p.platform,
  '',
  'Facts you may use:',
  facts.map(function (f) { return '- ' + f.label + ': ' + f.value; }).join('\n'),
  '',
  'The offer: ' + p.deliverables + (p.rate_card ? ' at £' + p.rate_card : ''),
  '',
  'Write the email.'
].join('\n');

return [{
  json: Object.assign({}, p, {
    facts: facts,
    fact_count: facts.length,
    brand_fact_count: brandFacts.length,
    subject: 'Partnership with ' + p.student + ' — ' + p.brand,
    body: skeleton,
    written_by: 'skeleton',
    _needs_writer: cfg.ai_enabled === true,
    _ai_system: system,
    _ai_user: user
  })
}];

// Reads the model's answer and keeps the skeleton when it cannot be trusted.
//
// A writer that times out, runs out of credits or returns something unparseable does not
// fail the run and does not silently send an empty email. The skeleton — assembled from
// facts, in code — stays, and the pitch is marked as unwritten so the audit downstream
// holds it for a human.
const p = $('build the pitch').item.json;
const resp = $json || {};

function textOf(r) {
  if (typeof r === 'string') return r;
  if (Array.isArray(r.content)) {
    return r.content.map(function (c) { return c.text || ''; }).join('');
  }
  return r.completion || r.text || '';
}

let subject = p.subject;
let body = p.body;
let by = 'skeleton';
let error = '';

const raw = textOf(resp).trim();
if (!raw) {
  error = resp.error ? (resp.error.message || String(resp.error)) : 'no answer from the writer';
} else {
  // The model was asked for JSON. Take the first {...} block rather than trusting that the
  // whole answer is clean — a leading "Here you go:" is the most common failure and it is
  // not worth a retry.
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end <= start) {
    error = 'writer did not return JSON';
  } else {
    try {
      const parsed = JSON.parse(raw.slice(start, end + 1));
      if (parsed.subject && parsed.body) {
        subject = String(parsed.subject).trim();
        body = String(parsed.body).trim();
        by = 'writer';
      } else {
        error = 'writer returned JSON without a subject or a body';
      }
    } catch (e) {
      error = 'writer returned malformed JSON: ' + e.message;
    }
  }
}

return [{
  json: Object.assign({}, p, {
    subject: subject,
    body: body,
    written_by: by,
    writer_error: error
  })
}];

// STOP: no writer configured — the skeleton pitch stands.
//
// The pitch is real: the facts are assembled, the numbers are the creator's own, and it is
// readable. It is also stiff, and the brief's third hard gate is that pitches never read
// templated. So it goes to the audit like every other pitch and will be held there unless
// it happens to pass — which the skeleton, by design, mostly does not.
//
// A blank AI_API_KEY means "a human finishes these", not "send them anyway".
const p = $json;

return [{
  json: Object.assign({}, p, {
    written_by: 'skeleton',
    writer_error: 'AI_API_KEY is blank — the skeleton was not rewritten'
  })
}];

// The personalisation gate. Their third hard gate, made checkable.
//
// > Sharp written English — pitches read human and personal from line one. Never templated.
// > NOT A FIT: your own application reads copy-paste.
//
// Five checks, and a pitch that fails any of them is HELD, not softened and sent:
//
//   1. enough facts    at least MIN_FACTS specific details drawn from the records, of
//                      which at least MIN_BRAND_FACTS must be about the BRAND. A pitch
//                      made mostly of the creator's own numbers is a CV, not outreach.
//   2. no template tells   nothing from BANNED_PHRASES survives.
//   3. length          inside MIN_WORDS..MAX_WORDS.
//   4. real recipient  not a role mailbox, not suppressed, a plausible address.
//   5. no invention    every number in the body appears in the facts. A model that
//                      rounds 84,000 up to "nearly 100k" has fabricated a media kit.
//
// Held pitches are not failures of the run. They are the run doing its job, and every one
// of them is listed with the reason.
const cfg = $('config').first().json;
const p = $json;

const holds = [];
const body = String(p.body || '');
const subject = String(p.subject || '');
const lower = (subject + ' ' + body).toLowerCase();

// 1. facts
if (Number(p.fact_count || 0) < Number(cfg.min_facts || 0)) {
  holds.push('only ' + (p.fact_count || 0) + ' usable facts, needs ' + cfg.min_facts +
    ' — the brand record is too thin to say anything specific');
}
if (Number(p.brand_fact_count || 0) < Number(cfg.min_brand_facts || 1)) {
  holds.push('only ' + (p.brand_fact_count || 0) + ' fact(s) about the brand itself, needs ' +
    cfg.min_brand_facts + ' — this reads as a CV, not as outreach');
}

// 2. template tells
const tells = (cfg.banned_phrases || []).filter(function (phrase) {
  return lower.indexOf(phrase) !== -1;
});
if (tells.length) holds.push('template tell: "' + tells.join('", "') + '"');

// 3. length
const words = body.split(/\s+/).filter(Boolean).length;
if (words < Number(cfg.min_words || 0)) holds.push(words + ' words, under the ' +
  cfg.min_words + '-word floor');
if (words > Number(cfg.max_words || 9999)) holds.push(words + ' words, over the ' +
  cfg.max_words + '-word ceiling');

// 4. recipient
const email = String(p.email || '').toLowerCase().trim();
const localPart = email.split('@')[0] || '';
const domain = email.split('@')[1] || '';
if (!/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email)) {
  holds.push('not a plausible address: "' + email + '"');
} else if ((cfg.role_prefixes || []).indexOf(localPart) !== -1) {
  holds.push('role mailbox (' + localPart + '@) — nobody owns it, and it is where bounce ' +
    'rates come from');
} else if ((cfg.suppression || []).indexOf(email) !== -1 ||
           (cfg.suppression || []).indexOf(domain) !== -1) {
  holds.push('suppressed');
}

// 5. no invention. Every number in the body has to be traceable to a fact or to the offer.
const known = (p.facts || []).map(function (f) { return String(f.value); })
  .concat([String(p.rate_card || ''), String(p.min_rate || ''), String(p.followers || ''),
           String(p.avg_views || '')])
  .join(' ').replace(/[,\s]/g, '');
const invented = (body.match(/\d[\d,.]*k?/gi) || []).filter(function (raw) {
  const n = raw.replace(/[,\s]/g, '');
  if (n.length < 3) return false;               // years, small counts, "2 stories"
  return known.indexOf(n.replace(/k$/i, '')) === -1 && known.indexOf(n) === -1;
});
if (invented.length) {
  holds.push('numbers not in the record: ' + invented.join(', ') +
    ' — a rounded-up follower count is a fabricated media kit');
}

// The skeleton is honest but stiff, and stiff is what the brief calls templated.
if (p.written_by === 'skeleton' && !holds.length) {
  holds.push('unwritten skeleton — reads as a template, needs a writer or a human');
}

return [{
  json: Object.assign({}, p, {
    word_count: words,
    audit_holds: holds,
    audit_passed: holds.length === 0,
    hold_reason: holds.join(' · ')
  })
}];

// The deliverability gate. Their second hard gate, and the one that fails CLOSED.
//
// > Deliverability literate — warmup, domain health, spam are second nature.
//
// An inbox sends only if it can be proved healthy. Five reasons it cannot:
//
//   warming        younger than MIN_WARMUP_DAYS. Nothing else about it matters.
//   bouncing       above MAX_BOUNCE_RATE — pulled until somebody cleans the list.
//   complaints     above MAX_SPAM_RATE.
//   unhealthy      platform health score below MIN_HEALTH_SCORE.
//   unknown        the platform will not report on it. HOLD_UNKNOWN_INBOX decides, and it
//                  ships true, because an unknown inbox is not a healthy one.
//
// Then two ceilings, both enforced here rather than left to the sending platform: per
// mailbox, and per DOMAIN. The second is the one people forget — five mailboxes on one
// domain each politely under their own cap will still cook the domain between them.
//
// Runs once for the whole batch, because a per-item version cannot count what the batch is
// already using.
const cfg = $('config').first().json;
const items = $input.all();

const inboxes = ((items[0] && items[0].json._roster && items[0].json._roster.inboxes) || [])
  .map(function (i) { return Object.assign({}, i); });

function health(inbox) {
  const reasons = [];
  const bounce = inbox.bounce_rate;
  const spam = inbox.spam_rate;
  const score = inbox.health_score;

  if (Number(inbox.warmed_days || 0) < Number(cfg.min_warmup_days || 0)) {
    reasons.push('warming (' + (inbox.warmed_days || 0) + 'd of ' + cfg.min_warmup_days + ')');
  }
  const unknown = bounce === null || bounce === undefined ||
    score === null || score === undefined;
  if (unknown) {
    if (cfg.hold_unknown_inbox) reasons.push('health not reported — held by default');
  } else {
    if (Number(bounce) > Number(cfg.max_bounce_rate)) {
      reasons.push('bounce ' + (Number(bounce) * 100).toFixed(1) + '% over ' +
        (Number(cfg.max_bounce_rate) * 100).toFixed(1) + '%');
    }
    if (spam !== null && spam !== undefined && Number(spam) > Number(cfg.max_spam_rate)) {
      reasons.push('spam complaints ' + (Number(spam) * 100).toFixed(2) + '% over ' +
        (Number(cfg.max_spam_rate) * 100).toFixed(2) + '%');
    }
    if (Number(score) < Number(cfg.min_health_score)) {
      reasons.push('health score ' + score + ' under ' + cfg.min_health_score);
    }
  }
  if (String(inbox.state || '').toLowerCase() === 'paused') reasons.push('paused');
  return reasons;
}

// Room left today, per mailbox and per domain, starting from what the platform says has
// already gone out.
const perInboxCap = Number(cfg.max_per_inbox_day || 0);
const perDomainCap = Number(cfg.max_per_domain_day || 0);
const domainUsed = {};
const usable = [];

inboxes.forEach(function (inbox) {
  const reasons = health(inbox);
  inbox._blocked = reasons;
  inbox._sent = Number(inbox.sent_today || 0);
  const d = String(inbox.domain || '');
  domainUsed[d] = (domainUsed[d] || 0) + inbox._sent;
  if (!reasons.length) usable.push(inbox);
});

// Fewest sent first, so the load spreads instead of hammering the first healthy mailbox.
usable.sort(function (a, b) { return a._sent - b._sent; });

const out = [];
let sent = 0;
let heldByAudit = 0;
const inboxReport = inboxes.map(function (i) {
  return { inbox: i.email, domain: i.domain, sent_today: i._sent,
    blocked: i._blocked.join(' · ') };
});

items.forEach(function (item) {
  const p = item.json;

  if (!p.audit_passed) {
    heldByAudit++;
    out.push({ json: Object.assign({}, p, {
      inbox: '', _send: false, send_state: 'held',
      send_reason: p.hold_reason, inbox_report: inboxReport }) });
    return;
  }

  // Pick the first healthy mailbox with room, whose domain also has room.
  let chosen = null;
  for (let i = 0; i < usable.length; i++) {
    const inbox = usable[i];
    const d = String(inbox.domain || '');
    const inboxRoom = perInboxCap <= 0 || inbox._sent < perInboxCap;
    const domainRoom = perDomainCap <= 0 || (domainUsed[d] || 0) < perDomainCap;
    if (inboxRoom && domainRoom) { chosen = inbox; break; }
  }

  if (!chosen) {
    const anyHealthy = usable.length > 0;
    out.push({ json: Object.assign({}, p, {
      inbox: '', _send: false, send_state: 'held',
      send_reason: anyHealthy
        ? 'every healthy inbox is at its daily ceiling — this rolls to the next run'
        : 'no inbox passed the health gate: ' + inboxes.map(function (i) {
            return i.email + ' (' + i._blocked.join('; ') + ')';
          }).join(' | '),
      inbox_report: inboxReport }) });
    return;
  }

  chosen._sent++;
  domainUsed[String(chosen.domain || '')] =
    (domainUsed[String(chosen.domain || '')] || 0) + 1;
  usable.sort(function (a, b) { return a._sent - b._sent; });
  sent++;

  out.push({ json: Object.assign({}, p, {
    inbox: chosen.email,
    inbox_domain: chosen.domain,
    _send: cfg.send_enabled === true,
    send_state: cfg.send_enabled ? 'queued' : 'preview',
    send_reason: cfg.send_enabled ? '' : 'preview — nothing is sent',
    // In test mode every pitch is redirected to one address, so a real brand contact is
    // never emailed while the copy is being checked.
    to: cfg.test_send && cfg.test_email ? cfg.test_email : p.email,
    inbox_report: inboxReport,
    _totals: { candidates: items.length, sendable: sent, held_by_audit: heldByAudit }
  }) });
});

out.forEach(function (o) {
  o.json._totals = { candidates: items.length, sendable: sent, held_by_audit: heldByAudit,
    inboxes_healthy: usable.length, inboxes_total: inboxes.length };
});
return out;

// The Instantly v2 POST /leads body. One lead, with the written pitch attached as custom
// variables so the campaign step can use {{subject}} and {{body}} verbatim.
//
// For Smartlead, change SEND_URL in config and the body here. Nothing else moves.
const cfg = $('config').first().json;
const p = $json;

const campaign = cfg.campaign_by_niche[p.niche] || cfg.campaign_id;

return [{
  json: Object.assign({}, p, {
    campaign: campaign,
    _body: {
      campaign: campaign,
      email: p.to,
      first_name: String(p.contact || '').split(' ')[0],
      last_name: String(p.contact || '').split(' ').slice(1).join(' '),
      company_name: p.brand,
      personalization: p.subject,
      custom_variables: {
        subject: p.subject,
        body: p.body,
        creator: p.student,
        handle: p.handle,
        niche: p.niche,
        sent_from: p.inbox,
        pitch_id: p.pitch_id
      }
    }
  })
}];

// Reads the sending platform's answer to each push and turns it into one honest line.
//
// A lead the campaign rejected is NOT recorded as sent. The brief's own words are "log
// every pitch, reply and booked deal in the student's dashboard — accurate and same day",
// and a log that quietly upgrades a 4xx into a send is the thing that makes a student's
// dashboard a lie.
const p = $('payload for the campaign').item.json;
const resp = $json || {};

// Instantly v2 answers with the created lead. A rejection comes back with an error or with
// nothing usable. `a && b` returns b, so the boolean coercion is deliberate.
const ok = !!(resp && !resp.error && (resp.id || resp.lead_id ||
  (resp.data && resp.data.id)));

return [{
  json: Object.assign({}, p, {
    sent: ok,
    lead_id: ok ? (resp.id || resp.lead_id || resp.data.id) : null,
    send_state: ok ? 'sent' : 'failed',
    send_reason: ok ? '' : (
      (resp.error && (resp.error.message || resp.error)) || 'no lead id returned'),
    sent_at: new Date().toISOString(),
    logged_at: new Date().toISOString()
  })
}];

// STOP: this pitch was not sent.
//
// Open this node to read the batch. In preview — how the workflow ships — every pitch is
// here, fully written, with the inbox it would have gone from, the facts it was built on,
// and for every held one, the audit's reason in plain words.
//
// That list is the deliverable of a first run, and it is also the only honest answer to
// their audition question: "two example pitches you've written — show us what personal and
// non-templated looks like."
const cfg = $('config').first().json;
const p = $json;

const why = p.send_state === 'held'
  ? p.send_reason
  : cfg.forced_preview
    ? 'PREVIEW (forced — the demo roster cannot email a real contact)'
    : cfg.preview_only
      ? 'PREVIEW — TEST_RUN is true and TEST_EMAIL is blank'
      : 'sending is not configured (SEND_API_KEY or CAMPAIGN_ID is blank)';

return [{
  json: Object.assign({}, p, {
    sent: false,
    lead_id: null,
    send_state: p.send_state === 'held' ? 'held' : 'preview',
    send_reason: why,
    sent_at: '',
    logged_at: new Date().toISOString()
  })
}];

// Every pitch, sent or held, as an Airtable row. Same day, which is the point.
//
// > Log every pitch, reply and booked deal in the student's dashboard — accurate and same
// > day. Careless or slow with logging: sloppy data breaks the whole system.
//
// Held pitches are logged too, with the reason. A log that only records successes cannot
// answer "why did we only send 180 of the 400 we planned", which is the first question
// anybody asks on a Friday.
//
// Batched ten to a request, because that is Airtable's maximum for POST /records. One
// request per pitch is four hundred requests for a normal day's run and will rate-limit
// long before it finishes.
const cfg = $('config').first().json;
const F = cfg.pitch_fields;
const items = $input.all();

const BATCH = 10;
const out = [];

for (let i = 0; i < items.length; i += BATCH) {
  const chunk = items.slice(i, i + BATCH).map(function (item) {
    const p = item.json;
    const row = {};
    row[F.pitch_id] = p.pitch_id;
    row[F.student_id] = p.student_id;
    row[F.student] = p.student;
    row[F.brand_id] = p.brand_id;
    row[F.brand] = p.brand;
    row[F.contact] = p.contact;
    row[F.email] = p.email;
    row[F.inbox] = p.inbox || '';
    row[F.subject] = p.subject;
    row[F.body] = p.body;
    row[F.facts_used] = (p.facts || []).map(function (f) {
      return f.label + '=' + f.value;
    }).join(' | ');
    row[F.sent_at] = p.sent_at || '';
    row[F.state] = p.send_state;
    row[F.hold_reason] = p.send_reason || '';
    return { fields: row };
  });
  out.push({
    json: {
      _batch: (i / BATCH) + 1,
      _count: chunk.length,
      // typecast lets Airtable create a missing single-select option rather than 422ing the
      // whole batch. A new hold reason should not stop the day's log being written.
      _body: { records: chunk, typecast: true }
    }
  });
}

if (!out.length) {
  return [{ json: { _batch: 0, _count: 0, _body: { records: [], typecast: true } } }];
}
return out;

// Did every pitch actually reach the dashboard?
//
// Counts the records Airtable says it created and compares that with the number of pitches
// this run produced. A mismatch is reported as a LOG GAP, with the number — it is not
// treated as a successful run that happened to write less.
//
// This is the check that makes "accurate and same day" a property rather than an intention.
const pitches = $('what happened').all().map(function (i) { return i.json; });
const responses = $input.all().map(function (i) { return i.json || {}; });

let created = 0;
const errors = [];
responses.forEach(function (r) {
  if (Array.isArray(r.records)) { created += r.records.length; return; }
  errors.push((r.error && (r.error.message || r.error.type || r.error)) ||
    'batch returned no records');
});

const gap = pitches.length - created;

return pitches.map(function (p) {
  return { json: Object.assign({}, p, {
    logged: gap === 0,
    log_gap: gap > 0,
    log_written: created,
    log_expected: pitches.length,
    log_reason: gap === 0 ? '' :
      gap + ' of ' + pitches.length + ' pitches did not reach the dashboard' +
      (errors.length ? ' (' + errors.join('; ') + ')' : '')
  }) };
});

// STOP: the pitch log was not written.
//
// This is a reportable state, not a quiet one. The brief treats same-day logging as part of
// the job, so a run that sent pitches and could not log them is called out in the summary
// with the count — it is a reconciliation the person working the inbox has to do by hand
// tomorrow.
//
// In preview nothing was sent either, so there is nothing to reconcile.
const cfg = $('config').first().json;
const items = $input.all();
const sent = items.filter(function (i) { return i.json.sent === true; }).length;

// Both the gap and its reason are read off what the run actually did, not off the mode it
// was configured in. A run that sent mail has a reconciliation to do whatever TEST_RUN said.
const gap = sent > 0;

return items.map(function (item) {
  return { json: Object.assign({}, item.json, {
    logged: false,
    log_gap: gap,
    log_reason: gap
      ? 'Airtable is not configured — ' + sent +
        ' sent pitch(es) are NOT in the dashboard and must be reconciled by hand'
      : 'nothing was sent, so there is nothing to log'
  }) };
});

// One message for the team, and a per-pitch record for whoever has to argue with it.
//
// The numbers that matter here are not "how many did we send". They are: how many were
// held and why, how many inboxes are healthy, and whether the log matched the sends. All
// three are the difference between 10,000 pitches a month and 10,000 pitches a month that
// keep landing.
const cfg = $('config').first().json;
const items = $input.all().map(function (i) { return i.json; });

const quiet = items.filter(function (j) { return j._has_work === false; })[0];
const pitches = items.filter(function (j) { return j._has_work !== false && j.pitch_id; });

const totals = (pitches[0] && pitches[0]._totals) || {};
const sent = pitches.filter(function (p) { return p.sent === true; });
const failed = pitches.filter(function (p) { return p.send_state === 'failed'; });
const held = pitches.filter(function (p) { return p.send_state === 'held'; });
const preview = pitches.filter(function (p) { return p.send_state === 'preview'; });

// Why things were held, grouped. A list of 180 reasons is not readable; six counts are.
const holdCounts = {};
held.forEach(function (p) {
  (p.audit_holds && p.audit_holds.length ? p.audit_holds : [p.send_reason || 'held'])
    .forEach(function (h) {
      // Group on the shape of the reason, not its detail, so "template tell: X" and
      // "template tell: Y" land in one bucket.
      const key = String(h).split(':')[0].split('—')[0].trim();
      holdCounts[key] = (holdCounts[key] || 0) + 1;
    });
});

const inboxReport = (pitches[0] && pitches[0].inbox_report) || [];
const blockedInboxes = inboxReport.filter(function (i) { return i.blocked; });

const logGap = pitches.filter(function (p) { return p.log_gap === true; }).length > 0;
const logReason = (pitches.filter(function (p) { return p.log_reason; })[0] || {}).log_reason;

const mode = cfg.forced_preview ? 'PREVIEW (forced — demo roster)'
  : cfg.preview_only ? 'PREVIEW — nothing sent'
  : cfg.test_send ? 'TEST — sent, redirected to ' + cfg.test_email
  : 'LIVE';

const lines = [];
lines.push('*Brand deal outreach* — ' + mode);
if (quiet) {
  lines.push(quiet.headline);
} else {
  lines.push(pitches.length + ' pitches written · ' + sent.length + ' sent · ' +
    held.length + ' held · ' + preview.length + ' preview');
  if (failed.length) lines.push(':warning: ' + failed.length + ' rejected by the campaign');
  lines.push('inboxes: ' + (totals.inboxes_healthy || 0) + ' of ' +
    (totals.inboxes_total || 0) + ' healthy');
  if (blockedInboxes.length) {
    lines.push('  ' + blockedInboxes.map(function (i) {
      return i.inbox + ' — ' + i.blocked;
    }).join('\n  '));
  }
  if (Object.keys(holdCounts).length) {
    lines.push('held because:');
    Object.keys(holdCounts).sort(function (a, b) {
      return holdCounts[b] - holdCounts[a];
    }).forEach(function (k) { lines.push('  ' + holdCounts[k] + ' × ' + k); });
  }
  if (logGap) lines.push(':rotating_light: log gap — ' + logReason);
}

// Per student, because that is how the money works: $50 per student per month.
const byStudent = {};
pitches.forEach(function (p) {
  const k = p.student || 'unknown';
  if (!byStudent[k]) byStudent[k] = { student: k, written: 0, sent: 0, held: 0 };
  byStudent[k].written++;
  if (p.sent) byStudent[k].sent++;
  if (p.send_state === 'held') byStudent[k].held++;
});

return [{
  json: {
    mode: cfg.mode,
    source: quiet ? quiet.source : (pitches[0] && pitches[0]._roster
      && pitches[0]._roster.source),
    written: pitches.length,
    sent: sent.length,
    held: held.length,
    preview: preview.length,
    failed: failed.length,
    hold_reasons: holdCounts,
    inboxes_healthy: totals.inboxes_healthy || 0,
    inboxes_total: totals.inboxes_total || 0,
    blocked_inboxes: blockedInboxes,
    log_gap: logGap,
    log_reason: logReason || '',
    by_student: Object.keys(byStudent).map(function (k) { return byStudent[k]; }),
    pitches: pitches.map(function (p) {
      return { pitch_id: p.pitch_id, student: p.student, brand: p.brand,
        contact: p.contact, email: p.email, inbox: p.inbox, subject: p.subject,
        words: p.word_count, facts: p.fact_count, state: p.send_state,
        reason: p.send_reason || '' };
    }),
    summary: lines.join('\n'),
    _alert_body: { text: lines.join('\n') }
  }
}];
